namespace srpss_core {

namespace {

// std140, the pattern pass's block (shaders/pattern.frag).
struct PatternBlock
{
    float targetSize[4]; // xy: the target in pixels
    float pattern[4];    // x: SurfacePattern
};
static_assert(sizeof(PatternBlock) == 32, "std140 Pattern block");

// A triangle over the whole viewport in clip space (no matrix: the content depends only on the texel it lands on).
constexpr float kFullTriangle[6] = { -1.0f, -1.0f, 3.0f, -1.0f, -1.0f, 3.0f };
constexpr int kTargetObjects = 3; // texture, render target, pass descriptor
constexpr int kPassObjects = 5;   // three buffers, bindings, pipeline

QAtomicInteger<int> g_liveSurfaces { 0 };
QAtomicInteger<int> g_liveResources { 0 };
QAtomicInteger<int> g_retiring { 0 };          // N3.8: retire entries in every window
QAtomicInteger<qint64> g_leftToServices { 0 }; // entries a registry left to their services when it went
QAtomicInteger<quint64> g_drawnGenerations { 0 }; // N5.7b: a surface's drawn frames, process-unique

quint64 nextDrawnGeneration()
{
    return g_drawnGenerations.fetchAndAddRelaxed(1) + 1;
}

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

struct RegistryEntry
{
    QPointer<QQuickWindow> window;
    std::weak_ptr<WindowSurfaces> surfaces;
};

QMutex &registryMutex()
{
    static QMutex mutex;
    return mutex;
}

QHash<QQuickWindow *, RegistryEntry> &registry()
{
    static QHash<QQuickWindow *, RegistryEntry> entries;
    return entries;
}

} // namespace

bool parseSurfacePattern(const QString &text, SurfacePattern *out)
{
    if (text == QLatin1String("texel_id")) {
        *out = SurfacePattern::TexelIdentity;
        return true;
    }
    if (text == QLatin1String("white")) {
        *out = SurfacePattern::White;
        return true;
    }
    return false;
}

QString surfacePatternName(SurfacePattern pattern)
{
    return pattern == SurfacePattern::White ? QStringLiteral("white") : QStringLiteral("texel_id");
}

bool parseSurfaceLayer(const QString &text, SurfaceLayer *out)
{
    if (text == QLatin1String("content")) {
        *out = SurfaceLayer::Content;
        return true;
    }
    if (text == QLatin1String("background")) {
        *out = SurfaceLayer::Background;
        return true;
    }
    return false;
}

QString surfaceLayerName(SurfaceLayer layer)
{
    return layer == SurfaceLayer::Background ? QStringLiteral("background") : QStringLiteral("content");
}

// ------------------------------------------------------------------------------------------------- Surface

struct Surface::Resources
{
    QRhi *rhi = nullptr;
    ColorTarget target;
    RhiOwned<QRhiBuffer> vertices;
    RhiOwned<QRhiBuffer> uniforms;
    RhiOwned<QRhiBuffer> conventions;
    RhiOwned<QRhiShaderResourceBindings> srb;
    RhiOwned<QRhiGraphicsPipeline> pipeline;
    bool staticUploaded = false;
};

Surface::Surface()
{
    g_liveSurfaces.fetchAndAddRelaxed(1);
}

Surface::~Surface()
{
    release();
    g_liveSurfaces.fetchAndAddRelaxed(-1);
}

int Surface::liveSurfaces()
{
    return g_liveSurfaces.loadRelaxed();
}

int Surface::liveResourcesTotal()
{
    return g_liveResources.loadRelaxed();
}

void Surface::setLive(int count)
{
    const int before = m_live.fetchAndStoreRelaxed(count);
    g_liveResources.fetchAndAddRelaxed(count - before);
}

QRhiTexture *Surface::texture() const
{
    return m_res ? m_res->target.texture.get() : nullptr;
}

QSize Surface::pixelSize() const
{
    return (m_res && m_res->target.texture) ? m_res->target.texture->pixelSize() : QSize();
}

QString Surface::lastPrime() const
{
    QMutexLocker lock(&m_mutex);
    return m_lastPrime;
}

void Surface::setPattern(SurfacePattern pattern)
{
    if (pattern == m_pattern)
        return;
    m_pattern = pattern;
    m_dirty.storeRelease(1);
}

void Surface::setContent(const std::shared_ptr<SurfaceContent> &content)
{
    if (content == m_content)
        return;
    if (m_content)
        m_content->release();
    m_content = content;
    m_dirty.storeRelease(1);
}

bool Surface::ensureTarget(QRhi *rhi, const QSize &pixels, QString *error, QRhiTexture::Format format)
{
    if (!rhi || pixels.width() < 1 || pixels.height() < 1) {
        *error = QStringLiteral("a surface needs a QRhi and a size of at least one pixel");
        return false;
    }
    if (m_res && m_res->rhi != rhi) {
        // The node (and with it this surface) goes with Qt's scene graph, so a second QRhi means a broken lifetime.
        *error = QStringLiteral("the surface was created on another QRhi");
        return false;
    }
    if (m_res && m_res->target.texture && m_res->target.texture->format() != format)
        release(); // another texel format: every object again (the content's pipelines follow its new pass)
    if (!m_res) {
        auto res = std::make_unique<Resources>();
        res->rhi = rhi;
        if (!createColorTarget(rhi, pixels, QByteArrayLiteral("srpss core surface"), &res->target, error, false,
                               format))
            return false;
        m_res = std::move(res);
        setLive(kTargetObjects);
        m_targetClear = false;                 // a new target's texels are not known to be anything
        m_drawnGeneration = 0;
        m_dirty.storeRelease(1);
        return true;
    }
    if (m_res->target.texture->pixelSize() == pixels)
        return true;
    m_targetClear = false;
    m_drawnGeneration = 0;
    // The same objects at the new size (the render pass descriptor and the pipeline stay compatible: same format).
    m_res->target.texture->setPixelSize(pixels);
    if (!m_res->target.texture->create() || !m_res->target.renderTarget->create()) {
        *error = QStringLiteral("the surface target could not be resized to %1 x %2").arg(pixels.width()).arg(
            pixels.height());
        release();
        return false;
    }
    m_res->target.generation = nextTargetGeneration(); // another target for a content's latch (L4)
    m_dirty.storeRelease(1);
    return true;
}

bool Surface::ensurePass(QString *error)
{
    Resources &r = *m_res;
    if (r.pipeline)
        return true;
    QRhi *rhi = r.rhi;
    const QShader vs = shaderFrom(pattern_vert_qsb, pattern_vert_qsb_size);
    const QShader fs = shaderFrom(pattern_frag_qsb, pattern_frag_qsb_size);
    if (!vs.isValid() || !fs.isValid()) {
        *error = QStringLiteral("the pattern pass's baked shaders are not valid");
        return false;
    }
    r.vertices.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer, sizeof(kFullTriangle)));
    r.uniforms.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(PatternBlock)));
    r.conventions.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(ConventionsBlock)));
    r.vertices->setName(QByteArrayLiteral("srpss core surface pattern vertices"));
    r.uniforms->setName(QByteArrayLiteral("srpss core surface pattern block"));
    r.conventions->setName(QByteArrayLiteral("srpss core surface conventions block"));
    if (!r.vertices->create() || !r.uniforms->create() || !r.conventions->create()) {
        *error = QStringLiteral("the pattern pass's buffers could not be created");
        return false;
    }
    r.srb.reset(rhi->newShaderResourceBindings());
    r.srb->setName(QByteArrayLiteral("srpss core surface pattern bindings"));
    r.srb->setBindings({
        QRhiShaderResourceBinding::uniformBuffer(0, QRhiShaderResourceBinding::FragmentStage, r.uniforms.get()),
        QRhiShaderResourceBinding::uniformBuffer(kConventionsBinding, QRhiShaderResourceBinding::FragmentStage,
                                                 r.conventions.get()) });
    if (!r.srb->create()) {
        *error = QStringLiteral("the pattern pass's bindings could not be created");
        return false;
    }
    r.pipeline.reset(rhi->newGraphicsPipeline());
    r.pipeline->setName(QByteArrayLiteral("srpss core surface pattern"));
    r.pipeline->setTargetBlends({ QRhiGraphicsPipeline::TargetBlend() }); // blending off: every texel is written
    r.pipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, fs } });
    QRhiVertexInputLayout layout;
    layout.setBindings({ { quint32(2 * sizeof(float)) } });
    layout.setAttributes({ { 0, 0, QRhiVertexInputAttribute::Float2, 0 } });
    r.pipeline->setVertexInputLayout(layout);
    r.pipeline->setCullMode(QRhiGraphicsPipeline::None);
    r.pipeline->setShaderResourceBindings(r.srb.get());
    r.pipeline->setRenderPassDescriptor(r.target.renderPass.get());
    if (!r.pipeline->create()) {
        *error = QStringLiteral("the pattern pass's pipeline could not be created");
        r.pipeline.reset();
        return false;
    }
    setLive(kTargetObjects + kPassObjects);
    return true;
}

bool Surface::record(QRhi *rhi, QRhiCommandBuffer *cb, bool *recorded, QString *error)
{
    *recorded = false;
    if (!dirty())
        return true; // at rest: the target keeps what it holds
    if (!m_res || !m_res->target.isValid()) {
        *error = QStringLiteral("the surface has no target");
        return false;
    }
    if (m_res->rhi != rhi || !cb) {
        *error = QStringLiteral("the surface is recorded on another QRhi, or with no command buffer");
        return false;
    }
    if (m_content) {
        if (m_content->keepsTarget(rhi, m_res->target)) {
            // The target keeps what it holds (a refused frame, a latched failure). A target holding nothing of the
            // content's own (a first build that failed: never written, undefined on Vulkan; audit N29 round 2, M4) is
            // cleared to transparent once by the surface's own pass, never shown as it is.
            m_dirty.storeRelease(0);
            if (!m_targetClear && !m_content->holdsFrame(m_res->target))
                return clearTarget(rhi, cb, recorded, error);
            return true;
        }
        // A mode's content (N2.5): its own passes into the same target, primed for the load first (rule C).
        const QString prime = primeForLoad(rhi, cb, m_res->target.texture.get());
        if (!m_content->record(rhi, cb, m_res->target, error)) {
            // Not retried every frame (audit 14 Nov, M2): the surface records again only when its content's inputs
            // change (a new frame, card, program or settings marks it dirty), and the content fails fast meanwhile.
            // A target with no frame of the content's in it is cleared once (M4); a frame of its own stays for the
            // route to fade the card out over (fade, never vanish).
            m_dirty.storeRelease(0);
            if (!m_targetClear && !m_content->holdsFrame(m_res->target)) {
                QString ignored;
                clearTarget(rhi, cb, recorded, &ignored);
            }
            if (!m_content->holdsFrame(m_res->target))
                m_drawnGeneration = 0;
            return false;
        }
        m_dirty.storeRelease(0);
        if (m_content->keptTargetLastRecord()) {
            // No pass: the target keeps the frame it holds (N5.7a, a still whose drawn inputs did not change).
            m_kept.fetchAndAddRelaxed(1);
            return true;
        }
        m_targetClear = !m_content->holdsFrame(m_res->target); // what the content did not draw it cleared by a draw
        m_drawnGeneration = m_targetClear ? 0 : nextDrawnGeneration(); // N5.7b: a new frame for the backdrop
        m_passes.fetchAndAddRelaxed(1);
        *recorded = true;
        QMutexLocker lock(&m_mutex);
        m_lastPrime = prime;
        return true;
    }
    return recordPattern(rhi, cb, m_pattern, recorded, error);
}

bool Surface::clearTarget(QRhi *rhi, QRhiCommandBuffer *cb, bool *recorded, QString *error)
{
    if (!recordPattern(rhi, cb, SurfacePattern::Transparent, recorded, error))
        return false;
    m_clears.fetchAndAddRelaxed(1);
    return true;
}

bool Surface::recordPattern(QRhi *rhi, QRhiCommandBuffer *cb, SurfacePattern pattern, bool *recorded, QString *error)
{
    if (!ensurePass(error))
        return false;
    Resources &r = *m_res;
    QRhiTexture *texture = r.target.texture.get();
    const QString prime = primeForLoad(rhi, cb, texture); // rule C: Qt Quick sampled it since our last pass
    QRhiResourceUpdateBatch *updates = rhi->nextResourceUpdateBatch();
    if (!r.staticUploaded) {
        updates->uploadStaticBuffer(r.vertices.get(), kFullTriangle);
        const ConventionsBlock block = targetConventions(rhi); // F1, F2: the block of a target the core owns
        updates->updateDynamicBuffer(r.conventions.get(), 0, sizeof(ConventionsBlock), &block);
        r.staticUploaded = true;
    }
    const QSize size = texture->pixelSize();
    PatternBlock block = {};
    block.targetSize[0] = float(size.width());
    block.targetSize[1] = float(size.height());
    block.pattern[0] = float(int(pattern));
    updates->updateDynamicBuffer(r.uniforms.get(), 0, sizeof(PatternBlock), &block);
    // The target keeps its contents (rule B): the triangle covers every texel with blending off, so nothing earlier
    // survives the pass.
    cb->beginPass(r.target.renderTarget.get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, updates);
    cb->setGraphicsPipeline(r.pipeline.get());
    cb->setViewport(QRhiViewport(0, 0, float(size.width()), float(size.height())));
    cb->setShaderResources();
    const QRhiCommandBuffer::VertexInput input(r.vertices.get(), 0);
    cb->setVertexInput(0, 1, &input);
    cb->draw(3);
    cb->endPass();
    m_dirty.storeRelease(0);
    m_targetClear = pattern == SurfacePattern::Transparent;
    m_drawnGeneration = m_targetClear ? 0 : nextDrawnGeneration();
    m_passes.fetchAndAddRelaxed(1);
    *recorded = true;
    QMutexLocker lock(&m_mutex);
    m_lastPrime = prime;
    return true;
}

void Surface::release()
{
    if (m_content)
        m_content->release(); // the content stays set: a later target records it again
    if (!m_res)
        return;
    m_res->pipeline.reset();
    m_res->srb.reset();
    m_res->conventions.reset();
    m_res->uniforms.reset();
    m_res->vertices.reset();
    m_res->target.reset();
    m_res.reset();
    setLive(0);
    m_targetClear = false;
    m_drawnGeneration = 0;
    m_dirty.storeRelease(1);
}

// ------------------------------------------------------------------------------------------------- WindowSurfaces

std::shared_ptr<WindowSurfaces> WindowSurfaces::forWindow(QQuickWindow *window)
{
    QMutexLocker lock(&registryMutex());
    RegistryEntry &entry = registry()[window];
    std::shared_ptr<WindowSurfaces> surfaces = entry.surfaces.lock();
    if (!surfaces || entry.window.isNull()) {
        surfaces = std::make_shared<WindowSurfaces>();
        surfaces->m_window = window;
        entry.window = window;
        entry.surfaces = surfaces;
        // Audit N38 M1: the window's frame count opens again after every rendered frame, once per registry (a direct
        // connection on the render thread; the window as context removes it with the window; a registry gone first
        // leaves a lambda that does nothing).
        const std::weak_ptr<WindowSurfaces> weak = surfaces;
        QObject::connect(window, &QQuickWindow::afterRendering, window, [weak]() {
            if (const std::shared_ptr<WindowSurfaces> live = weak.lock())
                live->frameRendered();
        }, Qt::DirectConnection);
    }
    return surfaces;
}

void WindowSurfaces::driverAttached()
{
    QMutexLocker lock(&m_mutex);
    ++m_drivers;
}

void WindowSurfaces::driverDetached()
{
    QMutexLocker lock(&m_mutex);
    if (m_drivers > 0)
        --m_drivers;
}

int WindowSurfaces::drivers() const
{
    QMutexLocker lock(&m_mutex);
    return m_drivers;
}

void WindowSurfaces::add(const std::shared_ptr<Surface> &surface)
{
    QMutexLocker lock(&m_mutex);
    for (const std::shared_ptr<Surface> &s : m_surfaces) {
        if (s == surface)
            return;
    }
    m_surfaces.append(surface);
}

void WindowSurfaces::remove(const Surface *surface)
{
    QMutexLocker lock(&m_mutex);
    for (qsizetype i = 0; i < m_surfaces.size(); ++i) {
        if (m_surfaces.at(i).get() == surface) {
            m_surfaces.removeAt(i);
            return;
        }
    }
}

int WindowSurfaces::count() const
{
    QMutexLocker lock(&m_mutex);
    return int(m_surfaces.size());
}

QList<std::shared_ptr<Surface>> WindowSurfaces::dirtySurfaces() const
{
    QList<std::shared_ptr<Surface>> dirty;
    QMutexLocker lock(&m_mutex);
    // D5.2's dependency order (N5.7a): the background layer first, then every other surface as it was added.
    for (const std::shared_ptr<Surface> &s : m_surfaces) {
        if (s->layer() == SurfaceLayer::Background && s->dirty())
            dirty.append(s);
    }
    for (const std::shared_ptr<Surface> &s : m_surfaces) {
        if (s->layer() != SurfaceLayer::Background && s->dirty())
            dirty.append(s);
    }
    return dirty;
}

// ------------------------------------------------------------------------------------------------- backdrops (N5.7b)

void WindowSurfaces::addBackdrop(const std::shared_ptr<BackdropPyramid> &pyramid)
{
    if (!pyramid)
        return;
    QMutexLocker lock(&m_mutex);
    for (const std::shared_ptr<BackdropPyramid> &p : m_backdrops) {
        if (p == pyramid)
            return;
    }
    m_backdrops.append(pyramid);
}

void WindowSurfaces::removeBackdrop(const BackdropPyramid *pyramid)
{
    QMutexLocker lock(&m_mutex);
    for (qsizetype i = 0; i < m_backdrops.size(); ++i) {
        if (m_backdrops.at(i).get() == pyramid) {
            m_backdrops.removeAt(i);
            return;
        }
    }
}

QList<std::shared_ptr<BackdropPyramid>> WindowSurfaces::backdrops() const
{
    QMutexLocker lock(&m_mutex);
    return m_backdrops;
}

std::shared_ptr<Surface> WindowSurfaces::backgroundSource() const
{
    // Render thread (drawnGeneration is the render thread's). The newest layer holding a frame; else the newest layer.
    QMutexLocker lock(&m_mutex);
    std::shared_ptr<Surface> newest;
    for (qsizetype i = m_surfaces.size() - 1; i >= 0; --i) {
        const std::shared_ptr<Surface> &s = m_surfaces.at(i);
        if (s->layer() != SurfaceLayer::Background)
            continue;
        if (s->drawnGeneration() != 0)
            return s;
        if (!newest)
            newest = s;
    }
    return newest;
}

// ------------------------------------------------------------------------------------------------- the retire list (N3.8)

WindowSurfaces::~WindowSurfaces()
{
    // No driver released these (none attached, or the nodes went after the driver's release): their services destroy
    // them when they stop, after Qt's QRhi is gone (D9 as built point 6). Nothing here may release them earlier.
    const int left = int(m_retired.size());
    m_retired.clear();
    if (left) {
        g_retiring.fetchAndAddRelaxed(-left);
        g_leftToServices.fetchAndAddRelaxed(left);
    }
}

void WindowSurfaces::retire(const std::shared_ptr<JobService> &service, quint64 output)
{
    if (!service || !output)
        return;
    {
        QMutexLocker lock(&m_mutex);
        Retired r;
        r.service = service;
        r.output = output;
        r.lastUse = m_edges.loadAcquire();
        m_retired.append(r);
        m_retiring.fetchAndAddOrdered(1);
        g_retiring.fetchAndAddRelaxed(1);
    }
    requestFrame(); // M2: the frames the release waits for are rendered even if nothing else changes
}

void WindowSurfaces::requestFrame()
{
    QQuickWindow *window = m_window;
    if (!window)
        return;
    m_frameRequests.fetchAndAddRelaxed(1);
    // Queued to the window's own thread with the window as context: dropped if the window is destroyed first.
    QMetaObject::invokeMethod(window, [window]() { window->update(); }, Qt::QueuedConnection);
}

int WindowSurfaces::releaseRetired(qint64 edge, int framesInFlight)
{
    QList<Retired> due;
    {
        QMutexLocker lock(&m_mutex);
        for (qsizetype i = m_retired.size() - 1; i >= 0; --i) {
            if (m_retired.at(i).lastUse + qMax(1, framesInFlight) <= edge)
                due.append(m_retired.takeAt(i));
        }
        m_retiring.fetchAndAddOrdered(-int(due.size()));
    }
    g_retiring.fetchAndAddRelaxed(-int(due.size()));
    for (const Retired &r : due)
        r.service->release(r.output); // queued to the job thread (never waits)
    if (retiring())
        requestFrame();               // M2: the next frame, for the entries still waiting (an edge per frame)
    return int(due.size());
}

int WindowSurfaces::releaseAllRetired()
{
    QList<Retired> all;
    {
        QMutexLocker lock(&m_mutex);
        all.swap(m_retired);
        m_retiring.fetchAndAddOrdered(-int(all.size()));
    }
    g_retiring.fetchAndAddRelaxed(-int(all.size()));
    for (const Retired &r : all)
        r.service->release(r.output);
    return int(all.size());
}

int WindowSurfaces::retiringTotal()
{
    return g_retiring.loadRelaxed();
}

qint64 WindowSurfaces::leftToServicesTotal()
{
    return g_leftToServices.loadRelaxed();
}

} // namespace srpss_core
